changeSet.sql:
ALTER TABLE event_definition_retinal_task
DROP CONSTRAINT IF EXISTS ck_event_def_retinal_task_allowed;
ALTER TABLE event_definition_retinal_task
ADD CONSTRAINT ck_event_def_retinal_task_allowed
CHECK (task IN ('fluid','ga','onl','pr','layers'));

rollback.sql:
ALTER TABLE event_definition_retinal_task
DROP CONSTRAINT IF EXISTS ck_event_def_retinal_task_allowed;
ALTER TABLE event_definition_retinal_task
ADD CONSTRAINT ck_event_def_retinal_task_allowed
CHECK (task IN ('fluid','ga','onl','pr'));

DELETE FROM event_definition_retinal_task
 WHERE task = 'layers'
   AND study_event_definition_id IN (
        SELECT study_event_definition_id FROM study_event_definition
         WHERE oc_oid = 'SE_RIS_VISIT'
   );
